/**
 * Msg is the write side of the national livestock registry: admit an office,
 * enrol a herd, identify an animal, certify its parentage, record a health
 * campaign, and move an animal from one keeper to another under supervision.
 */
export interface Msg {
  /** UpdateParams sets the module parameters. Governance only. */
  UpdateParams(request: MsgUpdateParams): Promise<MsgUpdateParamsResponse>;
  /**
   * RegisterAuthority admits a registry office. Governance only, and the
   * office must be a group account: enrolling a herd, certifying parentage and
   * validating a transfer are each a single signature otherwise.
   */
  RegisterAuthority(request: MsgRegisterAuthority): Promise<MsgRegisterAuthorityResponse>;
  /**
   * EnrolHerd records a herd at level 1 — the level that can actually cover
   * twenty-one million head, because it is costed per herd rather than per
   * animal.
   */
  EnrolHerd(request: MsgEnrolHerd): Promise<MsgEnrolHerdResponse>;
  /**
   * IdentifyAnimal records one animal at level 2, bound to its record by an
   * ISO 11784/11785 transponder fitted by an accredited agent.
   */
  IdentifyAnimal(request: MsgIdentifyAnimal): Promise<MsgIdentifyAnimalResponse>;
  /**
   * CertifyAnimal raises an animal to level 3: a DNA profile and photographic
   * biometrics, and a pedigree that refers to records rather than naming
   * names. The registry refuses a line it can prove impossible.
   */
  CertifyAnimal(request: MsgCertifyAnimal): Promise<MsgCertifyAnimalResponse>;
  /**
   * RecordHealthEvent is what turns a vaccination campaign into verifiable
   * coverage rather than a count of doses administered.
   */
  RecordHealthEvent(request: MsgRecordHealthEvent): Promise<MsgRecordHealthEventResponse>;
  /**
   * ProposeTransfer opens the supervised handover of an animal. Signed by the
   * current keeper, and it freezes the animal against a second transfer.
   */
  ProposeTransfer(request: MsgProposeTransfer): Promise<MsgProposeTransferResponse>;
  /**
   * AcceptTransfer is the buyer agreeing. A transfer nobody accepted is a
   * transfer that never happened, and requiring it is what stops a keeper
   * assigning an animal to somebody who never asked for it.
   */
  AcceptTransfer(request: MsgAcceptTransfer): Promise<MsgAcceptTransferResponse>;
  /**
   * AttestTransfer is the accredited agent or veterinarian swearing that the
   * animal presented is the animal on the record. This is the only claim in
   * the system the chain cannot check for itself, which is why it needs a
   * named person answering for it.
   */
  AttestTransfer(request: MsgAttestTransfer): Promise<MsgAttestTransferResponse>;
  /**
   * ObjectTransfer stops one. Open to anybody, because the person best placed
   * to notice a stolen animal being sold is rarely a party to the sale.
   */
  ObjectTransfer(request: MsgObjectTransfer): Promise<MsgObjectTransferResponse>;
  /**
   * CompleteTransfer moves the animal, once the window has run and the
   * attestations are in.
   */
  CompleteTransfer(request: MsgCompleteTransfer): Promise<MsgCompleteTransferResponse>;
  /**
   * RetireAnimal records a death, a slaughter or a sale out of the country.
   * The record stays: a pedigree refers to its ancestors, and deleting one
   * would silently break every descendant's line.
   */
  RetireAnimal(request: MsgRetireAnimal): Promise<MsgRetireAnimalResponse>;
  /** AccreditAgent admits one person as an attestor, or strikes them off. */
  AccreditAgent(request: MsgAccreditAgent): Promise<MsgAccreditAgentResponse>;
  /**
   * CancelTransfer withdraws a proposal the buyer never took up. Without it an
   * animal whose buyer simply never answers is frozen against any further sale
   * for good, and the seller has done nothing wrong.
   */
  CancelTransfer(request: MsgCancelTransfer): Promise<MsgCancelTransferResponse>;
  /** ResolveObjection is an office deciding whether an objection had substance. */
  ResolveObjection(request: MsgResolveObjection): Promise<MsgResolveObjectionResponse>;
  /** FreezeAnimal stops an animal moving while an inquiry runs. */
  FreezeAnimal(request: MsgFreezeAnimal): Promise<MsgFreezeAnimalResponse>;
  /** ReleaseAnimal ends a hold and returns the animal to circulation. */
  ReleaseAnimal(request: MsgReleaseAnimal): Promise<MsgReleaseAnimalResponse>;
}

